/**
 * The mailbox behind outreach: sending from the operator's own address and
 * reading replies from its inbox. One small interface, two implementations:
 * SMTP + IMAP for a real mailbox, and an in-memory one for tests.
 */
export interface OutgoingMessage {
  from: { name: string; address: string };
  to: string;
  subject: string;
  text: string;
  /** RFC Message-ID including angle brackets, generated by us before the first attempt. */
  messageId: string;
  inReplyTo?: string | null;
  references?: string[];
  headers?: Record<string, string>;
}

export interface SendResult {
  /** The server's final reply line. */
  response: string;
  /** Anything worth recording that did not stop the send (e.g. the copy could not be saved to Sent). */
  note?: string | null;
}

/**
 * auth: the mailbox refused the login (fix the credentials; nothing was sent)
 * rejected: the server refused this message or recipient for good (5xx)
 * temporary: the server asked to try later (4xx)
 * connection: the server could not be reached before the message was handed over
 * unknown: the outcome is not known (the connection broke while sending)
 */
export type MailErrorKind = "auth" | "rejected" | "temporary" | "connection" | "unknown";

export class MailSendError extends Error {
  constructor(
    message: string,
    public readonly kind: MailErrorKind,
    public readonly responseCode?: number,
  ) {
    super(message);
    this.name = "MailSendError";
  }
}

export interface InboundMessage {
  uid: number;
  messageId: string;
  inReplyTo: string | null;
  references: string[];
  from: { address: string; name: string };
  subject: string;
  text: string;
  date: string;
  /** Lower-cased header names. */
  headers: Record<string, string>;
  /** The beginning of the raw source, for matching bounces to the email they are about. */
  rawHead: string;
}

export interface InboxCursor {
  uid: number;
  uidValidity: string;
}

export interface MailProvider {
  key: string;
  /** The address mail is sent from. */
  address: string;
  send(msg: OutgoingMessage): Promise<SendResult>;
  /** Whether a message with this Message-ID is in the Sent folder; null when that cannot be told. */
  wasSent(messageId: string): Promise<boolean | null>;
  /** New inbox messages after the cursor, or received since `since` when there is no usable cursor. */
  fetchInbox(opts: { cursor: InboxCursor | null; since: Date; limit?: number }): Promise<{ messages: InboundMessage[]; cursor: InboxCursor | null }>;
  /** Checks both connections without sending anything. null = fine, otherwise the reason. */
  verify(): Promise<{ smtp: string | null; imap: string | null }>;
}
